  var arch_sd = max(abs(p.x) - 0.8, -0.92 - p.y);
  if (p.y > 0.08) { arch_sd = length(vec2f(p.x, p.y - 0.08)) - 0.8; }
  sd = mix(sd, arch_sd, arch);
