  let bend_by = (fract(h.y * 7.7) * 0.7 + 0.35) * mix(1.0, 0.45, tufted);
  let mid = tilt + bend_by * t * 0.5;
  let angle = tilt + bend_by * t;
  let strands = combed_now * wider * wider * m.c[3].w;
