        let middle = root_at + (root_at - zone) * TUFT_FAN * a + ((r2 - 0.5) * 1.7 * a + (r3 - 0.5) * 2.2 * a * a) / TUFT_BINS;
        // (as wide most of its length, then to a point)
        let thin = TUFT_BLADE / TUFT_BINS * (1.0 - pow(a, 3.0));
